<?php
require_once __DIR__.'/../includes/admin_layout.php'; $file=__DIR__.'/../data/orders.json'; $orders=readJson($file); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $id=$_POST['order_id']??''; $status=$_POST['status']??''; $allowed=['new','preparing','ready','completed','cancelled']; if($id && in_array($status,$allowed,true)){foreach($orders as &$o)if(($o['order_id']??'')===$id)$o['status']=$status;unset($o);writeJson($file,$orders);$msg='Order status updated.';}}
$filter=$_GET['status']??'all'; $shown=$filter==='all'?$orders:array_filter($orders,fn($o)=>($o['status']??'')===$filter); adminStart('Orders','orders'); if($msg):?><div class="notice success">✅ <?=h($msg)?></div><?php endif; ?><div class="filter-bar"><a class="<?= $filter==='all'?'selected':''?>" href="orders.php">All</a><?php foreach(['new','preparing','ready','completed','cancelled'] as $s):?><a class="<?= $filter===$s?'selected':''?>" href="orders.php?status=<?=$s?>"><?=ucfirst($s)?></a><?php endforeach;?></div><section class="admin-panel"><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Pickup</th><th>Status</th><th>Date</th></tr><?php foreach(array_reverse($shown) as $o): ?><tr><td><b>#<?=h($o['order_id']??'')?></b></td><td><?=h($o['customer_name']??'')?></td><td><?php foreach(($o['items']??[]) as $it): ?><div><?=h($it['name'])?> × <?=h($it['quantity'])?></div><?php endforeach;?></td><td>₹<?=number_format((float)($o['total']??0),2)?></td><td><?=h($o['payment_method']??'-')?><br><small><?=h($o['payment_status']??'')?></small></td><td><?=h($o['pickup_time']??'-')?></td><td><form method="post" class="inline-form"><input type="hidden" name="order_id" value="<?=h($o['order_id']??'')?>"><select name="status" onchange="this.form.submit()" class="form-control compact"><?php foreach(['new','preparing','ready','completed','cancelled'] as $s):?><option value="<?=$s?>" <?=($o['status']??'')===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select></form></td><td><?=h($o['created_at']??'')?></td></tr><?php endforeach;?></table></div><?php if(!$shown):?><div class="empty">No orders found.</div><?php endif;?></section><?php adminEnd();?>